/// Classify how a warm stretch ended and the graded tail's
/// probe count, from the final probe series: the exit verdict
/// [`warmup_and_probe`] records and the report prints.
fn classify_warm(probes: &[ProbeSummary]) -> (WarmExit, usize) {
    match warm_window(probes) {
        Some(w) => {
            let exit = if window_grades_a(w) {
                WarmExit::Settled
            } else {
                WarmExit::Unstable
            };
            (exit, w.len())
        }
        None => (WarmExit::Uncertified, probes.len()),
    }
}

input.new_string:
/// Whether the delivered clock held still across a window's
/// samples — the exit condition's second gate, the one that
/// separates "settled at the top" from a dwell one P-state
/// below it (a dwell is *steady*, so no timing test can).
///
/// - Anything short of clean same-CPU readings falls back to
///   timing-only (`true`): a missing `cpuinfo_avg_freq` (the
///   read is amd-pstate-specific) or a mid-window migration of
///   an unpinned main means there is no honest per-core series
///   to gate on.
fn clock_stable(samples: &[Option<crate::freq::FreqSample>]) -> bool {
    let mut min = u64::MAX;
    let mut max = 0u64;
    let mut cpu: Option<usize> = None;
    for s in samples {
        let Some(f) = s else { return true };
        match cpu {
            None => cpu = Some(f.cpu),
            Some(c) if c != f.cpu => return true,
            Some(_) => {}
        }
        min = min.min(f.khz);
        max = max.max(f.khz);
    }
    if max == 0 {
        return true;
    }
    (max - min) as f64 / max as f64 <= FREQ_STABLE_TOL
}

/// Classify how a warm stretch ended and the graded tail's
/// probe count, from the final probe series and the clock
/// series sampled alongside it: the exit verdict
/// [`warmup_and_probe`] records and the report prints.
///
/// - A window that grades A on timing but whose clock still
///   moved is [`WarmExit::Unstable`]: steady is not settled
///   when the box is mid-climb (the measured 7600x dwell).
fn classify_warm(
    probes: &[ProbeSummary],
    clock: &[Option<crate::freq::FreqSample>],
) -> (WarmExit, usize) {
    match warm_window(probes) {
        Some(w) => {
            let clock_w = &clock[clock.len().saturating_sub(w.len())..];
            let exit = if window_grades_a(w) && clock_stable(clock_w) {
                WarmExit::Settled
            } else {
                WarmExit::Unstable
            };
            (exit, w.len())
        }
        None => (WarmExit::Uncertified, probes.len()),
    }
}

