/// Keep the clock series parallel to the probe series: one
/// delivered-frequency sample per probe, taken at the exit
/// check right after the probe lands. Padding by length (rather
/// than pushing blindly) keeps the alignment across the process
/// warm / per-run handoff.
fn sample_clock(clock: &mut Vec<Option<crate::freq::FreqSample>>, probes_len: usize) {
    while clock.len() < probes_len {
        clock.push(crate::freq::avg_freq());
    }
}

