1	//! Layered configuration for defaults: built-in < XDG config file <
2	//! project-local file < CLI flags.
3	//!
4	//! - **XDG file** — `$XDG_CONFIG_HOME/iiac-perf/config.toml`, or
5	//!   `$HOME/.config/iiac-perf/config.toml` when `XDG_CONFIG_HOME`
6	//!   is unset. The per-user home for defaults and pin profiles.
7	//! - **Project-local file** — [`LOCAL_FILE`] in the current
8	//!   directory (no upward walk). Overrides the XDG file
9	//!   field-by-field; profiles merge by key.
10	//! - **CLI** — always wins, resolved in `main` after [`load`].
11	//!
12	//! A malformed or unreadable-but-present file is a hard error, so a
13	//! typo surfaces rather than silently reverting to built-ins.
14	
15	use std::collections::BTreeMap;
16	use std::path::PathBuf;
17	
18	use serde::Deserialize;
19	
20	use crate::bands::BandLabels;
21	
22	/// Project-local override filename, looked up in the current
23	/// directory only.
24	const LOCAL_FILE: &str = "iiac-perf.toml";
25	
26	/// Inclusive upper bound on `decimals`, mirroring the
27	/// `--decimals` CLI `value_parser` range.
28	const DECIMALS_MAX: u8 = 3;
29	
30	/// The on-disk TOML shape, before validation. Scalars are
31	/// `Option` so an absent key stays absent (letting a lower layer
32	/// or built-in default show through); unknown keys are rejected
33	/// to catch typos.
34	#[derive(Debug, Default, Deserialize)]
35	#[serde(deny_unknown_fields)]
36	struct RawConfig {
37	    /// Default `--duration` seconds.
38	    duration: Option<f64>,
39	    /// Default `--band-labels` style, as its lowercase name.
40	    band_labels: Option<String>,
41	    /// Default `--decimals` count.
42	    decimals: Option<u8>,
43	    /// Default `--settle-time` seconds.
44	    settle_time: Option<f64>,
45	    /// Named pin profiles: name -> `--pin` core spec.
46	    #[serde(default)]
47	    profiles: BTreeMap<String, String>,
48	}
49	
50	/// The merged, validated configuration handed to `main`.
51	///
52	/// Each scalar is `Option`: `None` means "no config opinion, use
53	/// the built-in default". Profiles are a flat name->spec map.
54	#[derive(Debug, Default, PartialEq)]
55	pub struct Config {
56	    /// Default `--duration` seconds, if configured.
57	    pub duration: Option<f64>,
58	    /// Default `--band-labels` style, if configured.
59	    pub band_labels: Option<BandLabels>,
60	    /// Default `--decimals` count, if configured.
61	    pub decimals: Option<u8>,
62	    /// Default `--settle-time` seconds, if configured.
63	    pub settle_time: Option<f64>,
64	    /// Named pin profiles: name -> `--pin` core spec.
65	    pub profiles: BTreeMap<String, String>,
66	}
67	
68	impl Config {
69	    /// Resolve a `--pin` spec against the configured profiles: a
70	    /// spec that names a profile expands to that profile's core
71	    /// spec; anything else is returned unchanged for
72	    /// [`crate::pin::parse_cores`] to parse as a raw core list.
73	    pub fn resolve_pin<'a>(&'a self, spec: &'a str) -> &'a str {
74	        self.profiles.get(spec).map(String::as_str).unwrap_or(spec)
75	    }
76	}
77	
78	/// The XDG config-file path: `$XDG_CONFIG_HOME/iiac-perf/config.toml`,
79	/// falling back to `$HOME/.config/...`. `None` if neither env var is
80	/// set (e.g. a stripped-down service environment).
81	fn xdg_path() -> Option<PathBuf> {
82	    let base = match std::env::var_os("XDG_CONFIG_HOME") {
83	        Some(x) if !x.is_empty() => PathBuf::from(x),
84	        _ => PathBuf::from(std::env::var_os("HOME")?).join(".config"),
85	    };
86	    Some(base.join("iiac-perf").join("config.toml"))
87	}
88	
89	/// Load and merge the XDG and project-local config files. Returns
90	/// the merged [`Config`] plus the paths of the files that actually
91	/// existed (for the startup banner). Built-in-default `Config` when
92	/// no file exists; errors on a present-but-unreadable or malformed
93	/// file.
94	///
95	/// Layering: start from the XDG file, then overlay the local file
96	/// (scalars replace, profiles merge by key), so the nearer file
97	/// wins per field.
98	pub fn load() -> Result<(Config, Vec<PathBuf>), String> {
99	    let mut raw = RawConfig::default();
100	    let mut loaded = Vec::new();
101	    if let Some(path) = xdg_path()
102	        && overlay(&mut raw, &path)?
103	    {
104	        loaded.push(path);
105	    }
106	    let local = PathBuf::from(LOCAL_FILE);
107	    if overlay(&mut raw, &local)? {
108	        loaded.push(local);
109	    }
110	    Ok((validate(raw)?, loaded))
111	}
112	
113	/// Read one config file and overlay it onto `base`: each present
114	/// scalar replaces `base`'s, and profiles are merged by key (the
115	/// file's entries win). Returns whether the file existed; a missing
116	/// file is a no-op returning `false`.
117	fn overlay(base: &mut RawConfig, path: &PathBuf) -> Result<bool, String> {
118	    let text = match std::fs::read_to_string(path) {
119	        Ok(t) => t,
120	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(false),
121	        Err(e) => return Err(format!("reading {}: {e}", path.display())),
122	    };
123	    let over: RawConfig =
124	        toml::from_str(&text).map_err(|e| format!("parsing {}: {e}", path.display()))?;
125	    if over.duration.is_some() {
126	        base.duration = over.duration;
127	    }
128	    if over.band_labels.is_some() {
129	        base.band_labels = over.band_labels;
130	    }
131	    if over.decimals.is_some() {
132	        base.decimals = over.decimals;
133	    }
134	    if over.settle_time.is_some() {
135	        base.settle_time = over.settle_time;
136	    }
137	    base.profiles.extend(over.profiles);
138	    Ok(true)
139	}
140	
141	/// Validate a merged [`RawConfig`] into a [`Config`]: map the
142	/// `band_labels` name to the enum, range-check `decimals`, and
143	/// reject a negative `settle_time`.
144	fn validate(raw: RawConfig) -> Result<Config, String> {
145	    let band_labels = match raw.band_labels {
146	        None => None,
147	        Some(s) => Some(match s.as_str() {
148	            "zpn" => BandLabels::Zpn,
149	            "frac" => BandLabels::Frac,
150	            "both" => BandLabels::Both,
151	            other => {
152	                return Err(format!(
153	                    "band_labels: {other:?} is not one of zpn, frac, both"
154	                ));
155	            }
156	        }),
157	    };
158	    if let Some(d) = raw.decimals
159	        && d > DECIMALS_MAX
160	    {
161	        return Err(format!(
162	            "decimals: {d} exceeds the maximum of {DECIMALS_MAX}"
163	        ));
164	    }
165	    if let Some(t) = raw.settle_time
166	        && t < 0.0
167	    {
168	        return Err(format!("settle_time: {t} is negative"));
169	    }
170	    Ok(Config {
171	        duration: raw.duration,
172	        band_labels,
173	        decimals: raw.decimals,
174	        settle_time: raw.settle_time,
175	        profiles: raw.profiles,
176	    })
177	}
178	
